action.command:
cat > /tmp/verify.sh <<'EOF'
bash -c '
source /app/init.sh >/dev/null 2>&1
fail=0
[ "$DEV_HOME" = "/workspace" ] || { echo "FAIL DEV_HOME=[$DEV_HOME]"; fail=1; }
[ "$PROJECT_ROOT" = "/workspace/project" ] || { echo "FAIL PROJECT_ROOT=[$PROJECT_ROOT]"; fail=1; }
[ "$API_KEY" = "sk-test-12345-abcdef" ] || { echo "FAIL API_KEY=[$API_KEY]"; fail=1; }
[ "$DB_URL" = "postgres://user:pass@localhost:5432/devdb" ] || { echo "FAIL DB_URL=[$DB_URL]"; fail=1; }
case ":$PATH:" in *":/workspace/tools/bin:"*) :;; *) echo "FAIL PATH tools=[$PATH]"; fail=1;; esac
case ":$PATH:" in *":/workspace/scripts:"*) :;; *) echo "FAIL PATH scripts"; fail=1;; esac
command -v devtool >/dev/null || { echo "FAIL devtool"; fail=1; }
command -v buildhelper >/dev/null || { echo "FAIL buildhelper"; fail=1; }
[ $fail -eq 0 ] && echo ALLPASS || echo SOMEFAIL
'
EOF
chmod +x /tmp/verify.sh; /tmp/verify.sh

